def comps(g,val):
    g=np.array(g); H,W=g.shape; seen=np.zeros_like(g,bool); out=[]
    for i in range(H):
        for j in range(W):
            if g[i,j]==val and not seen[i,j]:
                st=[(i,j)];seen[i,j]=True;cells=[]
                while st:
                    y,x=st.pop();cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        y2,x2=y+dy,x+dx
                        if 0<=y2<H and 0<=x2<W and g[y2,x2]==val and not seen[y2,x2]:
                            seen[y2,x2]=True;st.append((y2,x2))
                out.append(cells)
    return out
