def maxcomp(blk,val):
    H,W=blk.shape; seen=np.zeros_like(blk,bool); best=0
    for r in range(H):
        for c in range(W):
            if blk[r][c]==val and not seen[r][c]:
                st=[(r,c)]; seen[r][c]=1; n=0
                while st:
                    x,y=st.pop(); n+=1
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<H and 0<=b<W and blk[a][b]==val and not seen[a][b]:
                            seen[a][b]=1; st.append((a,b))
                best=max(best,n)
    return best
